-- atomic_refund_termination_clawback_fresh(uuid,text,text,timestamp with time zone,text,text,text,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.atomic_refund_termination_clawback_fresh(p_user_id uuid, p_subscription_id text, p_event_id text, p_refund_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_invoice_scope_review_reason text DEFAULT NULL::text, p_reason text DEFAULT 'stripe_refund'::text, p_refund_id text DEFAULT NULL::text, p_now timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(transaction_id uuid, balance_after integer, clawback_amount integer, applied_clawback_amount integer, shortfall_amount integer, already_applied boolean, termination_written boolean, already_terminated boolean, grant_reversed boolean, already_reversed boolean, credits_granted integer, consumed_amount integer, resolved_period_key text, review_required boolean, review_reason text, idempotency_key text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
